/// The diagnostic-log members of [AgentCli]: the fa.log writer
/// (`_logDiagnostic`/`_appendDiagnosticLog`), the short session id for log
/// lines (`_logSid`) and the log path resolver (`_diagnosticLogPath`).
/// Split out of `agent_cli.dart` to keep that file under the repo's
/// 2800-line size gate. Same library (a `part of`), so the extension sees
/// the class's private members; the `_diagnosticLogDirEnsured` field stays
/// on the class — extensions hold no fields.
part of 'agent_cli.dart';

/// Diagnostic-log members of [AgentCli].
extension AgentCliDiagLog on AgentCli {
  /// Writes a diagnostic line to the log file (`~/.fah/logs/fa.log`).
  /// TUI/stderr stay clean — the AutoCompactor hook streams progress to
  /// the user, the log captures everything for post-mortem.
  ///
  /// Issue #2117: every call declares a [level] (default `info`) and a
  /// [category] (default `lifecycle`); the FILE sink gate applies before
  /// any work is queued, and the rendered line carries the level tag
  /// (fa.log keeps its shape and destination beyond the level tags).
  ///
  /// gh-2097: the append rides the serialized `_diagLogChain` — a burst
  /// of diagnostics lands complete and in order, never racing itself on
  /// the same file, and exit paths drain the chain so nothing is dropped
  /// (the old unawaited fire-and-forget lost rapid bursts at process
  /// exit).
  void _logDiagnostic(
    String message, {
    LogLevel level = LogLevel.info,
    LogCategory category = LogCategory.lifecycle,
  }) {
    final path = _diagnosticLogPath;
    if (path == null) return;
    if (!config.logging.filePasses(level, category)) return;
    _diagLogChain = _diagLogChain
        .then(
          (_) => _appendDiagnosticLog(
            path,
            message,
            level: level,
            category: category,
          ),
        )
        // The appender already swallows its own errors; this keeps the
        // chain alive regardless so one failure can never drop every
        // later line with it.
        .catchError((Object _) {});
  }

  /// gh-2097: drains the diagnostic-append chain — every exit path
  /// awaits this so the process cannot die with pending lines in the
  /// chain (the last thing the process does must never be a pending
  /// log write). Issue #2248 AC4: when the sink is failing, the drain
  /// also dumps the in-memory ring to stderr, so exit never loses the
  /// buffered post-mortem either.
  Future<void> flushDiagnosticLog() async {
    await _diagLogChain;
    _dumpDiagRingToStderr(exitDrain: true);
  }

  /// Test seam: emit one diagnostic line exactly as production callers
  /// do (gh-2097 burst/drop coverage; the level/category ride through
  /// for the #2117 sink tests).
  @visibleForTesting
  void logDiagnosticForTest(
    String message, {
    LogLevel level = LogLevel.info,
    LogCategory category = LogCategory.lifecycle,
  }) => _logDiagnostic(message, level: level, category: category);

  /// gh-2178: wires the quarantine report onto the CLI notice channel —
  /// the same line rides fa.log at warn level (the diagnostics file
  /// keeps the forensic copy; the reporter's per-record dedupe keeps a
  /// repeated turn from spamming either surface).
  void wireQuarantineNotice(void Function(String message) onNotice) {
    SessionQuarantine.onQuarantined = (line) {
      onNotice(line);
      _logDiagnostic(line, level: LogLevel.warn);
    };
  }

  /// Short session id for diagnostic log lines: parallel fa processes share
  /// one fa.log, so every lifecycle line names its session (post-mortem
  /// "who held the busy row" starts here).
  String get _logSid {
    final id = _session?.cachedId;
    if (id == null || id.isEmpty) return '-';
    return id.length <= 8 ? id : id.substring(0, 8);
  }

  /// Appends one rendered line to [path], creating the log directory on
  /// first use. Isolated from [_logDiagnostic] so the public entry point
  /// stays small.
  ///
  /// Issue #2117: the line is REDACTED (every rendered line, every sink)
  /// and carries the level tag after the timestamp — the default file
  /// shape is today's `ISO message` with ` level` inserted; a configured
  /// `logging.format` renders the pattern instead.
  Future<void> _appendDiagnosticLog(
    String path,
    String message, {
    required LogLevel level,
    required LogCategory category,
  }) async {
    final settings = config.logging;
    final safe = config.redactionPipeline?.redact(message) ?? message;
    final line = settings.format == null
        ? '${DateTime.now().toIso8601String()} ${level.name} $safe\n'
        : '${settings.format!.render(
            LogEvent(time: DateTime.now(), elapsed: DateTime.now().difference(_loggingBoot), sid: _logSid, level: level, category: category, message: safe),
            timeFormat: settings.timeFormat,
          )}\n';
    // Issue #2248 AC4: the append is BOUNDED (the same session-IO knob) —
    // wedge #1's log went silent because the log appends themselves hung;
    // a hung or failed append now trips the sink's failure mode instead
    // of stalling the whole diagnostic chain behind it.
    Result<void, FileError> result;
    try {
      if (!_diagnosticLogDirEnsured) {
        _diagnosticLogDirEnsured = true;
        await _env.createDir('${config.homeDir}/.fah/logs', recursive: true);
        await _rotateDiagnosticLogIfOversized(path);
      }
      result = await _boundedLogAppend(path, line);
    } on Object catch (error) {
      result = Err(FileError(FileErrorCode.unknown, '$error'));
    }
    if (result.isOk) {
      if (_ioState.diagFailing) await _recoverDiagSink(path);
      return;
    }
    _noteDiagSinkFailure(path, result.errorOrNull!);
    _emitDiagFallbackLine(line);
    _bufferDiagLine(line);
  }

  /// One fa.log append under the session-IO bound (RC round-1: the
  /// recovery flush ran unbounded inside the gh-2097 chain — a
  /// fail→ok→hang fs would have wedged the chain and the exit drain,
  /// the exact class this PR eliminates). A timeout surfaces as an Err
  /// flush result instead of awaiting forever.
  Future<Result<void, FileError>> _boundedLogAppend(String path, String line) =>
      _env
          .appendFile(path, line)
          .timeout(
            config.sessionIoTimeout,
            onTimeout: () => Err(
              FileError(
                FileErrorCode.aborted,
                'diagnostic log append timed out',
              ),
            ),
          );

  /// AC4: first-failure marker — `fa_log_sink=fail(errno=...)` rides the
  /// stderr fallback (the file sink is the thing that is down); the boot
  /// line family keeps the failure greppable.
  void _noteDiagSinkFailure(String path, FileError error) {
    final state = _ioState;
    if (!state.diagFailing) {
      state.diagFailing = true;
      state.diagFirstErrno = diagSinkErrnoLabel(error);
      _diagFallback(
        'fa_log_sink=fail(${state.diagFirstErrno ?? 'unknown'}) '
        'path=$path error=${error.message} — lines buffer in memory '
        'and ride stderr until the file sink recovers',
      );
    }
  }

  /// AC4: while failing, every line also goes to stderr (the diagnostics
  /// channel — headless hosts route writeln to stderr; the TUI transcript
  /// shows it, which is the point: the log must never go blind silently).
  void _emitDiagFallbackLine(String line) => _diagFallback(line.trimRight());

  /// AC4: bounded in-memory ring (last [diagSinkRingCapacity] lines).
  void _bufferDiagLine(String line) {
    final ring = _ioState.diagRing;
    ring.add(line);
    if (ring.length > diagSinkRingCapacity) {
      ring.removeAt(0);
    }
  }

  /// AC4: first successful write after a failure — flush the ring into
  /// the file (best-effort per line; a still-failing or TIMED-OUT flush
  /// keeps the buffer and the failing state), then mark the recovery
  /// with `log_sink_recovered buffered=N` so the post-mortem knows
  /// exactly which lines were delayed. Every append runs under the
  /// session-IO bound (RC round-1: an unbounded flush here could wedge
  /// the append chain on a fail→ok→hang fs). Awaited inside the append
  /// chain, so the flush lines never race the live appends that follow.
  Future<void> _recoverDiagSink(String path) async {
    final state = _ioState;
    final buffered = List<String>.of(state.diagRing);
    state.diagRing.clear();
    var flushed = 0;
    for (final bufferedLine in buffered) {
      final landed = await _boundedLogAppend(path, bufferedLine);
      if (landed.isOk) {
        flushed++;
      } else {
        _bufferDiagLine(bufferedLine);
      }
    }
    state.diagFailing = false;
    final errno = state.diagFirstErrno;
    state.diagFirstErrno = null;
    final marker = await _boundedLogAppend(
      path,
      '${DateTime.now().toIso8601String()} info '
      'log_sink_recovered buffered=$flushed '
      'failed_as=${errno ?? 'unknown'}\n',
    );
    if (!marker.isOk) {
      state.diagFailing = true;
      state.diagFirstErrno = errno;
      _diagFallback('log_sink_recovered buffered=$flushed (marker failed)');
      return;
    }
    _diagFallback('fa_log_sink=recovered buffered=$flushed flushed to file');
  }

  /// AC4/exit: dumps the still-unflushed ring to stderr — called from
  /// [flushDiagnosticLog] so a process that dies while the sink is down
  /// prints what it buffered instead of losing it.
  void _dumpDiagRingToStderr({required bool exitDrain}) {
    final state = _ioState;
    if (!state.diagFailing && state.diagRing.isEmpty) return;
    for (final line in state.diagRing) {
      _diagFallback(line.trimRight());
    }
    final count = state.diagRing.length;
    state.diagRing.clear();
    if (exitDrain && count > 0) {
      _diagFallback(
        'fa_log_sink=exit_drain buffered=$count dumped to stderr '
        '(file sink never recovered)',
      );
    }
  }

  /// The stderr/route fallback writer. CliIO.writeln is the diagnostics
  /// channel (stderr on headless hosts) — used instead of raw `stderr`
  /// so lib/src stays dart:io-free and the app host can route it.
  void _diagFallback(String text) {
    try {
      io.writeln(text);
    } on Object {
      // The fallback of the fallback must never throw either.
    }
  }

  /// Rotates [path] to `fa.log.1` when it exceeds
  /// [AgentCli.diagnosticLogMaxBytes]. Runs once per process (first log
  /// write), so parallel fa processes can race the rename — losing a few
  /// diagnostics lines is acceptable for a post-mortem file. The rename
  /// keeps the previous log available; a backend that reports rename as
  /// unsupported (CwdOverrideEnv forwards the capability only when the
  /// delegate has it) falls back to truncating in place.
  Future<void> _rotateDiagnosticLogIfOversized(String path) async {
    final info = await _env.fileInfo(path);
    final size = info.valueOrNull?.size ?? 0;
    if (size <= AgentCli.diagnosticLogMaxBytes) return;
    final renamed = await _env.renamePath(path, '$path.1');
    if (renamed.isOk) return;
    await _env.writeFile(path, '');
  }

  /// Path of the diagnostic log file under `~/.fah/logs/fa.log`. Null
  /// when the host has no `homeDir` (web build, sandbox).
  String? get _diagnosticLogPath {
    final home = config.homeDir;
    if (home == null || home.isEmpty) return null;
    return '$home/.fah/logs/fa.log';
  }
}

/// Per-process state for the issue #2248 CLI surfaces. Extensions hold
/// no fields, and `agent_cli.dart` rides the 2800-line gate — one object
/// on the class carries the fa.log sink's self-failure state (AC4) and
/// the sessions-container size memo (AC6).
final class AgentCliIoState {
  /// AC4: whether the fa.log sink is currently failing (stderr fallback
  /// active, ring buffering).
  bool diagFailing = false;

  /// AC4: the errno label of the failure that opened the episode
  /// (`errno=24: Too many open files` shape), echoed by the recovery
  /// marker.
  String? diagFirstErrno;

  /// AC4: the in-memory ring of lines that failed to land — flushed to
  /// the file on recovery, dumped to stderr on exit drain. Bounded at
  /// [diagSinkRingCapacity]; the oldest line falls off beyond it.
  final diagRing = <String>[];

  /// AC6: the sessions-container size memo — boot starts the walk
  /// unawaited; /stats awaits the same future (never recomputes).
  Future<ContainerSizeStats?>? containerSizeFuture;
}

/// Ring capacity: the incident's log hole spanned ~100 lifecycle lines
/// over minutes; 500 keeps a healthy post-mortem margin without
/// unbounded memory. ponytail: fixed cap, configurable only if a real
/// session ever needs more.
const int diagSinkRingCapacity = 500;

final _errnoInMessage = RegExp(r'\(errno (\d+): ([^)]*)\)');

/// The errno label a FileError carries into the `fa_log_sink=fail(...)`
/// marker. The env layer embeds the raw OS reason in the message
/// (`... (errno 24: Too many open files)`, issue #2248 AC1) — that is
/// the parse here, so lib/src stays dart:io-free (fake envs in tests
/// inject the same shape).
String diagSinkErrnoLabel(FileError error) {
  final match = _errnoInMessage.firstMatch(error.message);
  if (match != null) return 'errno=${match.group(1)}: ${match.group(2)}';
  final message = error.message.trim();
  return message.isEmpty ? 'unknown' : message;
}

/// The chain half of the usage fold (gh-1241): walking a session's JSONL
/// record chain — the source of truth — into per-segment [FoldRequest]
/// lists, then into a [UsageLedger].
///
/// The scanner reads RAW lines, not typed records: it needs only a handful
/// of fields per record, and the chain's giant ledger-only payloads
/// (`model_request_summary`, blob tables) must not pay full
/// materialization. Known-irrelevant blob records (`trajectory_prompt_blob`
/// /`trajectory_manifest_blob`/`trajectory_wire_dump`) are skipped by
/// substring without `jsonDecode` — they can be megabytes of base64 and
/// contribute nothing to token sums.
///
/// Segment boundaries are `usage_segment_start` custom records appended by
/// the host at every session start/resume; a chain without any markers
/// folds as ONE segment (old sessions still produce a sane ledger).
/// Segment order is chain sequence (E4) — record timestamps land in the
/// artifact as informational `openedAt`/`closedAt` only.
library;

import 'dart:convert';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';

import '../compaction/token_estimation.dart' show estimateTokens;
import '../context.dart' show messageFromJson;
import 'usage_fold.dart';
import 'usage_ledger.dart';

/// The custom record type that opens a usage segment (gh-1241 I1): appended
/// by the host at every session start/resume, consumed by
/// [UsageChainScanner] as the segment boundary.
const String usageSegmentStartCustomType = 'usage_segment_start';

/// The `model_request_summary` custom record type (trajectory ledger).
const String modelRequestSummaryCustomType = 'model_request_summary';

/// byModel key for requests whose model is unknown (errored requests that
/// never produced an assistant message, and their zero-filled fallbacks).
const String unknownUsageModel = 'unknown';

/// Chars-per-token of the shared chars/4 estimation heuristic
/// (`estimateTokens` in `token_estimation.dart`) — the fold's estimated
/// fallback prices input at the SAME rate the compaction estimator uses,
/// so an estimated request prices like the same request priced by the ctx
/// meter.
const int usageCharsPerToken = 4;

/// Custom-record types the scanner skips without decoding (megabyte-wide
/// ledger payloads irrelevant to token sums).
const _skipDecodeCustomTypes = [
  'trajectory_prompt_blob',
  'trajectory_manifest_blob',
  'trajectory_wire_dump',
];

/// One segment's raw fold input: the requests in chain order plus the
/// boundary timestamps derived from chain records.
final class UsageChainSegment {
  /// Creates a [UsageChainSegment].
  const UsageChainSegment({
    required this.requests,
    this.model,
    this.openedAt,
    this.closedAt,
    this.traceLines = const [],
  });

  /// The segment's provider requests.
  final List<FoldRequest> requests;

  /// Optional compact request and tool-result diagnostics in chain order.
  final List<String> traceLines;

  /// The segment's LAST-SEEN model id (gh-1460): the model that served the
  /// final request — stamped into the `fa-tokens:` segment-close line so
  /// the row is attributable (and priceable) downstream. `null` when the
  /// segment never observed a model (legacy chains, zero-filled fallbacks
  /// only): the line then keeps its legacy shape.
  final String? model;

  /// First contributing record's chain timestamp (or the opening marker's).
  final DateTime? openedAt;

  /// Last contributing record's chain timestamp.
  final DateTime? closedAt;
}

/// The scan result: per-segment requests plus the chain fingerprint used
/// for stale/corrupt detection (E3) and idempotency (I6).
final class UsageChainScan {
  /// Creates a [UsageChainScan].
  const UsageChainScan({
    required this.segments,
    required this.recordCount,
    required this.chainHash,
    this.usageIncomplete = false,
    this.emptyTrailingSegment = false,
  });

  /// Segments in chain order (always at least one).
  final List<UsageChainSegment> segments;

  /// Number of record lines consumed (header and torn lines excluded).
  final int recordCount;

  /// `sha256:`-prefixed fingerprint over the consumed raw record lines.
  final String chainHash;

  /// gh-1643: true when at least one request started and never finalized —
  /// its `model_request_summary` dangled (killed mid-stream, provider
  /// error, abort) and its contribution is PARTIAL (estimated input only,
  /// output unknown). Consumers must never read such a fold as complete
  /// accounting.
  final bool usageIncomplete;

  /// Whether the last marker opened a segment with no contributing records.
  final bool emptyTrailingSegment;
}

/// Scans raw session-chain JSONL lines into [UsageChainScan].
final class UsageChainScanner {
  /// Creates a [UsageChainScanner].
  const UsageChainScanner({this.captureTrace = false, this.redactToolName});

  /// Collect compact diagnostics without changing the folded totals.
  final bool captureTrace;

  /// Redacts tool names before they are encoded into diagnostic lines.
  final String Function(String)? redactToolName;

  /// Scans [lines] (the session file's raw lines, header included).
  UsageChainScan scan(Iterable<String> lines) {
    final state = _ScanState(
      captureTrace: captureTrace,
      redactToolName: redactToolName,
    );
    for (final raw in lines) {
      final line = raw.trimRight();
      if (line.isEmpty) continue;
      // Cheap pre-check for the giant blob records: hashed, counted, never
      // decoded.
      final skippedDecode = _isBlobRecord(line);
      final decoded = skippedDecode ? <String, dynamic>{} : _decode(line);
      if (decoded == null) continue; // torn line: contributes nothing
      final type = decoded['type'];
      if (type == 'session') continue; // header line
      state.noteRecord(line);
      if (skippedDecode) continue;
      final timestamp = DateTime.tryParse(
        decoded['timestamp'] as String? ?? '',
      );
      if (type == 'custom' &&
          decoded['customType'] == usageSegmentStartCustomType) {
        _handleMarker(timestamp, state);
        continue;
      }
      // Every other consumed record contributes its timestamp to the
      // current segment (its closedAt, or firstRecordAt fallback).
      state.current().noteRecordAt(timestamp);
      if (type == 'custom') {
        _handleSummary(decoded, timestamp, state);
        continue;
      }
      if (type != 'message') continue;
      _handleMessage(decoded, timestamp, state);
    }
    return state.finish();
  }

  /// Whether [line] carries one of the megabyte-wide ledger blob records
  /// the scanner skips without decoding.
  static bool _isBlobRecord(String line) {
    for (final blobType in _skipDecodeCustomTypes) {
      if (line.contains('"customType":"$blobType"')) return true;
    }
    return false;
  }

  /// Handles a segment-marker record. A marker OPENS the segment it
  /// introduces: the first marker on a chain claims the (lazy) first
  /// segment; a later marker closes the previous segment only when it
  /// carried anything (an empty trailing segment from a killed boot is
  /// not materialized, I1). The marker itself is not a "contributing"
  /// record: the previous segment's closedAt stays its last request's
  /// timestamp.
  void _handleMarker(DateTime? timestamp, _ScanState state) {
    if (!state.segments.lastOrNull.hasContentOrNull) {
      state.current().setOpenedAt(timestamp);
    } else {
      state.closeSegment(timestamp);
    }
  }

  /// Handles a `custom` record that is not a segment marker: a
  /// `model_request_summary` becomes the pending pair for the assistant
  /// message its request produces. A summary superseded by another summary
  /// means the earlier request never finalized (gh-1643) — it is flushed
  /// as a fallback, never silently dropped.
  void _handleSummary(
    Map<String, dynamic> decoded,
    DateTime? timestamp,
    _ScanState state,
  ) {
    if (decoded['customType'] == modelRequestSummaryCustomType) {
      final superseded = state.pending;
      if (superseded != null) {
        state.current().addRequest(superseded.fallback(), superseded.at);
        state.usageIncomplete = true;
      }
      state.pending = _PendingSummary.fromData(decoded['data'], timestamp);
    }
  }

  /// Handles an assistant `message` record: only assistant messages
  /// produce a [FoldRequest], priced from the provider-reported usage or —
  /// when the provider omitted usage — estimated from the paired request
  /// summary.
  void _handleMessage(
    Map<String, dynamic> decoded,
    DateTime? timestamp,
    _ScanState state,
  ) {
    final message = decoded['message'];
    if (message is! Map) return;
    if (message['role'] == 'toolResult') {
      state.current().addToolResult(message);
      return;
    }
    if (message['role'] != 'assistant') return;
    final request = _foldAssistant(
      message.cast<String, dynamic>(),
      state.pending,
    );
    state.current().addRequest(request, state.pending?.at ?? timestamp);
    state.pending = null;
  }

  static Map<String, dynamic>? _decode(String line) {
    try {
      final decoded = jsonDecode(line);
      if (decoded is Map) return decoded.cast<String, dynamic>();
    } on Object {
      // Torn/foreign line: the tolerant reader skips it.
    }
    return null;
  }

  FoldRequest _foldAssistant(
    Map<String, dynamic> message,
    _PendingSummary? summary,
  ) {
    final model =
        (message['model'] as String?) ??
        (message['responseModel'] as String?) ??
        unknownUsageModel;
    final usage = message['usage'];
    final usageMap = usage is Map ? usage.cast<String, dynamic>() : null;
    final input = usageMap?['input'] as int? ?? 0;
    final output = usageMap?['output'] as int? ?? 0;
    final cacheRead = usageMap?['cacheRead'] as int? ?? 0;
    final cacheWrite = usageMap?['cacheWrite'] as int? ?? 0;
    final totalTokens = usageMap?['totalTokens'] as int? ?? 0;
    // Provider-reported iff any count is non-zero: AssistantMessage.usage
    // is non-nullable and providers that omit usage deserialize to
    // Usage.zero (AC4's fake-provider case).
    final reported =
        totalTokens > 0 ||
        input > 0 ||
        output > 0 ||
        cacheRead > 0 ||
        cacheWrite > 0;
    if (reported) {
      return FoldRequest(
        model: model,
        input: input,
        output: output,
        cacheRead: cacheRead,
        cacheWrite: cacheWrite,
        reasoning: usageMap?['reasoning'] as int?,
        source: UsageSource.reported,
      );
    }
    // Estimated fallback (I3): input priced from the paired request
    // summary's outbound chars, output from the assistant payload's
    // chars — both at the shared chars/4 rate. Estimation failures degrade
    // to zero, never a crash.
    final inputChars = summary?.inputChars ?? 0;
    return FoldRequest(
      model: model,
      input: (inputChars / usageCharsPerToken).ceil(),
      output: _estimateAssistantOutput(message),
      source: UsageSource.estimated,
    );
  }

  int _estimateAssistantOutput(Map<String, dynamic> message) {
    try {
      return estimateTokens(messageFromJson(message));
    } on Object {
      return 0;
    }
  }
}

/// Mutable scan state: the segment list, the pending request summary, the
/// consumed-record fingerprint material, and the segment-close/finish
/// policy. Extracted from [UsageChainScanner.scan] so the per-record-type
/// handlers stay small enough for the CRAP ratchet.
final class _ScanState {
  _ScanState({required this.captureTrace, this.redactToolName});

  final bool captureTrace;
  final String Function(String)? redactToolName;
  final BytesBuilder _bytes = BytesBuilder(copy: false);
  final List<_ScanSegment> segments = [];
  _PendingSummary? pending;
  var recordCount = 0;

  /// gh-1643: at least one request started and never finalized (its
  /// `model_request_summary` dangled) — the fold's totals cover partial
  /// knowledge only, so consumers must see the incomplete marker.
  var usageIncomplete = false;

  /// The current segment, creating the first lazily so a chain with no
  /// markers still folds as ONE segment.
  _ScanSegment current() {
    if (segments.isEmpty) {
      segments.add(_ScanSegment(captureTrace, redactToolName));
    }
    return segments.last;
  }

  /// Hashes and counts a consumed record line.
  void noteRecord(String line) {
    recordCount += 1;
    _bytes
      ..add(utf8.encode(line))
      ..add(const [10]);
  }

  /// A segment boundary: a summary whose request never produced an
  /// assistant message (provider error, abort) counts, with its KNOWN
  /// request-side volume marked estimated — never silently dropped (E1),
  /// and never silent zeros (gh-1643: the estimate rides the fallback).
  void closeSegment(DateTime? boundaryAt) {
    if (pending case final summary?) {
      segments.last.addRequest(summary.fallback(), summary.at);
      usageIncomplete = true;
      pending = null;
    }
    segments.add(
      _ScanSegment(captureTrace, redactToolName)..setOpenedAt(boundaryAt),
    );
  }

  /// Builds the scan result. A dangling summary still counts — with its
  /// known request-side volume (gh-1643), and flagged incomplete. A
  /// header-only chain still yields ONE (empty) segment so the ledger
  /// schema stays stable. A marker that closed a contentful segment
  /// opens a new one — when nothing followed it (the first drive after
  /// a resume errored before any request record landed), the empty
  /// trailing segment is trimmed, not materialized: otherwise
  /// resumedCount inflates (I1 noise) and the flush's fa-tokens line
  /// reports a zero-count segment labeled "reported".
  UsageChainScan finish() {
    if (pending case final summary?) {
      segments.lastOrNull?.addRequest(summary.fallback(), summary.at);
      usageIncomplete = true;
      pending = null;
    }
    if (segments.isEmpty) {
      segments.add(_ScanSegment(captureTrace, redactToolName));
    }
    final emptyTrailingSegment =
        segments.length > 1 && !segments.last.hasContent;
    while (segments.length > 1 && !segments.last.hasContent) {
      segments.removeLast();
    }
    return UsageChainScan(
      segments: [
        for (final segment in segments)
          UsageChainSegment(
            requests: segment.requests,
            model: segment.lastModel,
            openedAt: segment.openedAt ?? segment.firstRecordAt,
            closedAt: segment.closedAt,
            traceLines: segment.traceLines,
          ),
      ],
      recordCount: recordCount,
      chainHash: 'sha256:${sha256.convert(_bytes.toBytes())}',
      usageIncomplete: usageIncomplete,
      emptyTrailingSegment: emptyTrailingSegment,
    );
  }
}

/// Mutable scan state for one segment.
final class _ScanSegment {
  _ScanSegment(this.captureTrace, this.redactToolName);

  final bool captureTrace;
  final String Function(String)? redactToolName;
  final List<String> traceLines = [];
  DateTime? openedAt;
  final List<FoldRequest> requests = [];
  DateTime? firstRecordAt;
  DateTime? closedAt;

  /// The LAST-SEEN model on a real request (gh-1460): zero-filled fallbacks
  /// (`unknownUsageModel`) and blank ids are not observations — they never
  /// overwrite a model the segment actually saw, and a segment of only
  /// fallbacks stays model-less so the segment-close line keeps its legacy
  /// shape.
  String? lastModel;

  /// Whether anything contributed to this segment (a marker claiming an
  /// empty virgin segment does not count — killed boots leave nothing).
  bool get hasContent => requests.isNotEmpty || firstRecordAt != null;

  /// Adds a request and, when it observed a real model, records it as the
  /// segment's last-seen model.
  void addRequest(FoldRequest request, DateTime? timestamp) {
    requests.add(request);
    if (captureTrace) {
      traceLines.add(
        'usage_request: ${jsonEncode({'t': timestamp?.toIso8601String(), 'in': request.input, 'out': request.output, 'cr': request.cacheRead, 'source': request.source.wire})}',
      );
    }
    if (request.model.isNotEmpty && request.model != unknownUsageModel) {
      lastModel = request.model;
    }
  }

  void addToolResult(Map message) {
    if (!captureTrace) return;
    final name = message['toolName'];
    final content = message['content'];
    if (name is! String || content is! List) return;
    final bytes = utf8.encode(jsonEncode(content)).length;
    final safeName = redactToolName?.call(name) ?? name;
    traceLines.add('tool_result:${Uri.encodeComponent(safeName)}:$bytes');
  }

  void setOpenedAt(DateTime? at) {
    openedAt ??= at;
  }

  void noteRecordAt(DateTime? at) {
    firstRecordAt ??= at;
    if (at != null) closedAt = at;
  }
}

/// Null-safe [ _ScanSegment.hasContent] probe for the boundary branch.
extension on _ScanSegment? {
  bool get hasContentOrNull => this?.hasContent ?? false;
}

/// A `model_request_summary` record waiting for the assistant message its
/// request produces (the summary always lands first on the chain).
final class _PendingSummary {
  _PendingSummary(this.inputChars, this.systemPromptChars, this.at);

  /// Request submission timestamp from the summary record.
  final DateTime? at;

  /// Σ `chars` of the summary's outbound request messages — the estimated
  /// input-token basis.
  final int inputChars;

  /// Length of the outbound system prompt (gh-1643): part of the request's
  /// known input volume, counted by the dangling-request fallback.
  final int systemPromptChars;

  factory _PendingSummary.fromData(Object? data, DateTime? timestamp) {
    var chars = 0;
    var systemChars = 0;
    if (data is Map) {
      final rawSystem = data['systemPromptChars'];
      if (rawSystem is int) systemChars = rawSystem;
      final messages = data['messages'];
      if (messages is List) {
        for (final message in messages) {
          if (message is Map) {
            chars += message['chars'] as int? ?? 0;
          }
        }
      }
      // issue #1882 AC1: stripped records fold older messages into a
      // {count, chars} aggregate — its chars are part of the estimation
      // basis exactly like the per-message ones.
      final dropped = data['droppedMessages'];
      if (dropped is Map) {
        chars += dropped['chars'] as int? ?? 0;
      }
    }
    return _PendingSummary(chars, systemChars, timestamp);
  }

  /// The request never produced an assistant message (gh-1643): count its
  /// KNOWN request-side volume — estimated input at the shared chars/4
  /// rate (the same basis the persisted summary carried at request
  /// submission); output is unknown and stays 0. Marked estimated, and the
  /// scan flags the chain usageIncomplete — never a silent zero.
  FoldRequest fallback() => FoldRequest(
    model: unknownUsageModel,
    input: ((inputChars + systemPromptChars) / usageCharsPerToken).ceil(),
    output: 0,
    source: UsageSource.estimated,
  );
}

/// The rebuildable fold (gh-1241): records are the source of truth, so the
/// ledger is always recomputable from the chain — SIGKILL loses nothing
/// (AC3), running twice yields byte-identical output (I6).
final class UsageChainFolder {
  /// Creates a [UsageChainFolder].
  const UsageChainFolder({this.folder = const UsageFolder()});

  /// The pure fold math.
  final UsageFolder folder;

  /// Folds the session chain's raw [lines] into a [UsageLedger].
  UsageLedger foldChain({
    required String sessionId,
    required Iterable<String> lines,
    UsageChainScanner scanner = const UsageChainScanner(),
  }) {
    final scan = scanner.scan(lines);
    return foldScan(sessionId: sessionId, scan: scan);
  }

  /// Folds an already scanned chain, including any collected diagnostics.
  UsageLedger foldScan({
    required String sessionId,
    required UsageChainScan scan,
  }) {
    final segments = <UsageSegment>[
      for (var i = 0; i < scan.segments.length; i++)
        folder.foldSegment(
          i,
          scan.segments[i].requests,
          model: scan.segments[i].model,
          openedAt: scan.segments[i].openedAt,
          closedAt: scan.segments[i].closedAt,
        ),
    ];
    return UsageLedger(
      sessionId: sessionId,
      segments: segments,
      total: folder.totalOf(segments),
      chainRecords: scan.recordCount,
      chainHash: scan.chainHash,
      usageIncomplete: scan.usageIncomplete,
    );
  }
}

